local Scoring = {}
function Scoring.passed(score) return score >= 50 end
return Scoring

local Text = {}
function Text.slug(value) return string.lower((string.gsub(value, "%s+", "-"))) end
return Text

local M = { courseCount = 20 }
function M.lessonCount(perCourse) return M.courseCount * perCourse end
return M

local Progress = {}
function Progress.percent(done, total) if total <= 0 then return 0 end return math.floor(done * 100 / total) end
return Progress
